        overloadIndex: "\u041D\u0430\u0438\u043B\u0443\u0447\u0448\u0435\u0435 \u0441\u043E\u0432\u043F\u0430\u0434\u0435\u043D\u0438\u0435: {index} \u043F\u0435\u0440\u0435\u0433\u0440\u0443\u0437\u043A\u0438",
